import sys
lines = sys.stdin.read().splitlines()
out = []
q = []
if lines:
    m = int(lines[0])
    for line in lines[1:1+m]:
        cmd = line.split()
        if not cmd: continue
        if cmd[0] == 'PUSH':
            x = int(cmd[1])
            q.append(x)
            for _ in range(len(q) - 1): q.append(q.pop(0))
        elif cmd[0] == 'POP': out.append(str(q.pop(0)))
        elif cmd[0] == 'TOP': out.append(str(q[0]))
        elif cmd[0] == 'EMPTY': out.append('true' if not q else 'false')
print(' '.join(out))
